#!/usr/bin/env node
// Export a first-party plugin package (libs/papercusp/plugins/<name>) as the ROOT of a
// standalone public mirror repository, the way Papercusp/papercusp-worker is laid out.
//
// Why: the monorepo that holds libs/papercusp/plugins is private, so a Cupboard listing that
// points into it cannot be installed by anyone outside Papercusp
// (cupboard-distributable-integrations-2026-10-10#D-014). The in-tree package stays the
// source of truth; the mirror is a DERIVED copy, regenerated by this script, never edited
// by hand.
//
// Guarantees:
//   - Only COMMITTED content is exported (read from a git ref, default HEAD of the plugins
//     submodule), so an uncommitted edit can never leak into a public repository.
//   - The package must be self-contained: no relative import that escapes the package
//     directory, and no bare-specifier import that is neither a Node builtin nor declared
//     in the package's own package.json. A mirror that cannot run outside the tree is
//     refused rather than published.
//   - A LICENSE file is generated from the manifest's SPDX `license` when the package has
//     none. Only MIT is generated; any other licence must ship its own LICENSE file.
//   - Text that only means something inside the private monorepo (a home-directory path,
//     a work-item or agent-session id, a dated plan slug, an operator port, an internal
//     schema) is refused, so a source comment that cites internal context fails here and in
//     this script's test, not at publish time.
//
// Usage:
//   node scripts/plugin-mirror-export.mjs --package slack --out /tmp/papercusp-slack [--ref HEAD]
// Prints MIRROR_FILE <path> per exported file, then MIRROR_OK files=<n>, or MIRROR_REFUSED
// <reason> and exits 1.
//
// Publishing (updates an existing mirror repository):
//   node scripts/plugin-mirror-export.mjs --package slack --out /tmp/papercusp-slack-publish \
//     --push https://github.com/Papercusp/papercusp-slack.git
// Clones the remote into --out (which must not exist or be empty), replaces the tree with the
// export, and pushes ONE commit on top of the remote's history (a fast-forward). Unchanged
// content makes no commit. Prints MIRROR_PUBLISHED head=<sha> src=<sha> or
// MIRROR_UNCHANGED head=<sha>. The remote must already exist: creating a public repository is
// a deliberate one-time step (`gh repo create <owner>/<repo> --public`).

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { builtinModules } from 'node:module';
import { dirname, join, posix, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { transformSync } from 'esbuild';

import { isCliEntry } from '@papercusp/operator-core/lib/util/cli-entry';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const DEFAULT_PLUGINS_REPO = join(REPO_ROOT, 'libs', 'papercusp');
const CODE_EXT = /\.(?:mjs|cjs|js)$/;
const NAME_RE = /^[a-z0-9][a-z0-9._-]*$/;

/** Read every committed file of `plugins/<name>` at `ref` from the plugins repository. */
export function readCommittedPackage({ pluginsRepo = DEFAULT_PLUGINS_REPO, name, ref = 'HEAD' }) {
  if (!NAME_RE.test(name)) throw new Error(`invalid package name: ${name}`);
  const prefix = `plugins/${name}/`;
  const listing = execFileSync('git', ['-C', pluginsRepo, 'ls-tree', '-r', '--name-only', ref, '--', prefix], {
    encoding: 'utf8',
  });
  const paths = listing.split('\n').filter(Boolean);
  if (paths.length === 0) throw new Error(`no committed files under ${prefix} at ${ref}`);
  return paths.map((full) => ({
    path: full.slice(prefix.length),
    // execFileSync throws on a non-zero git exit, so a missing blob can never become an
    // empty file in the mirror.
    content: execFileSync('git', ['-C', pluginsRepo, 'show', `${ref}:${full}`], { maxBuffer: 64 * 1024 * 1024 }),
  }));
}

/** Every module specifier a JS source file imports or requires. */
export function importSpecifiers(source) {
  const out = [];
  const patterns = [
    /\bimport\s+(?:[^'"()]*?\s+from\s+)?['"]([^'"]+)['"]/g,
    /\bexport\s+[^'"()]*?\s+from\s+['"]([^'"]+)['"]/g,
    /\bimport\(\s*['"]([^'"]+)['"]\s*\)/g,
    /\brequire\(\s*['"]([^'"]+)['"]\s*\)/g,
  ];
  for (const re of patterns) for (const m of source.matchAll(re)) out.push(m[1]);
  return out;
}

function isBuiltin(spec) {
  if (spec.startsWith('node:')) return true;
  const base = spec.split('/')[0];
  return builtinModules.includes(spec) || builtinModules.includes(base);
}

function packageNameOf(spec) {
  const parts = spec.split('/');
  return spec.startsWith('@') ? parts.slice(0, 2).join('/') : parts[0];
}

/** Problems that would stop the package running from a standalone checkout. */
export function selfContainmentProblems(files) {
  const problems = [];
  const pkgJson = files.find((f) => f.path === 'package.json');
  let declared = new Set();
  if (pkgJson) {
    const pkg = JSON.parse(pkgJson.content.toString('utf8'));
    declared = new Set([
      ...Object.keys(pkg.dependencies ?? {}),
      ...Object.keys(pkg.peerDependencies ?? {}),
      ...Object.keys(pkg.optionalDependencies ?? {}),
    ]);
  }
  for (const file of files) {
    if (!CODE_EXT.test(file.path)) continue;
    for (const spec of importSpecifiers(file.content.toString('utf8'))) {
      if (spec.startsWith('.') || spec.startsWith('/')) {
        const target = posix.normalize(posix.join(posix.dirname(file.path), spec));
        if (spec.startsWith('/') || target === '..' || target.startsWith('../')) {
          problems.push(`${file.path}: import '${spec}' escapes the package directory`);
        }
        continue;
      }
      if (isBuiltin(spec)) continue;
      if (!declared.has(packageNameOf(spec))) {
        problems.push(`${file.path}: import '${spec}' is not a Node builtin and not declared in package.json`);
      }
    }
  }
  return problems;
}

// Text that only means something inside the private monorepo. A public mirror carrying it leaks
// internal context and points readers at things they cannot open. A pack's own plan.md may use
// its local P-NNN / D-NNN item ids, so those are deliberately not listed.
const INTERNAL_REFERENCES = [
  { re: /\/home\/[^\s'"`)]+/, what: 'an absolute home-directory path' },
  { re: /papercupai-workspace/, what: 'the monorepo checkout name' },
  { re: /\b(?:packages\/operator-core|apps\/operator)\//, what: 'a monorepo source path' },
  { re: /\b(?:WI|EI)-\d{3,}\b/, what: 'an internal work-item id' },
  { re: /\bsu-[0-9a-f]{5,}\b/, what: 'an internal agent session id' },
  { re: /\b[a-z][a-z0-9]*(?:-[a-z0-9]+)+-20\d\d-\d\d-\d\d\b/, what: 'an internal plan slug' },
  { re: /\bharness_shared\b/, what: 'an internal database schema' },
  { re: /(?:127\.0\.0\.1|localhost):3[01]70\b/, what: 'an internal operator port' },
];

/** Lines that cite internal context; a mirror must describe behaviour instead. */
export function internalReferenceProblems(files) {
  const problems = [];
  for (const file of files) {
    if (file.content.includes(0)) continue; // binary
    const lines = file.content.toString('utf8').split('\n');
    lines.forEach((line, index) => {
      for (const { re, what } of INTERNAL_REFERENCES) {
        const match = re.exec(line);
        if (match) {
          problems.push(`${file.path}:${index + 1}: ${what} ('${match[0]}'); describe the behaviour instead of citing internal context`);
        }
      }
    });
  }
  return problems;
}

export function mitLicense({ holder = 'Papercusp', year = new Date().getUTCFullYear() } = {}) {
  return `MIT License

Copyright (c) ${year} ${holder}

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE.
`;
}

// SDK-generated providers ship their executable bundle. TypeScript is a build input;
// esbuild's source-path comments are metadata. Parse/reprint rather than deleting text
// that might occur in a JavaScript string. Retained runtime dependencies still fail closed.
function compiledProviderFiles(files, manifest, problems) {
  if (!manifest?.provider || typeof manifest.main !== 'string') return files;
  const main = posix.normalize(manifest.main);
  const entry = files.find((f) => f.path === main);
  const generated = /^\/\/ Generated (?:from ([^\r\n]+?) )?by @papercusp\/plugin-sdk\/scripts\/build-provider-daemons\.mjs\. Do not edit\./;
  const match = entry && generated.exec(entry.content.toString('utf8'));
  if (!match?.[1]) return files;
  const source = posix.normalize(posix.join(posix.dirname(main), match[1]));
  if (source.startsWith('../') || posix.isAbsolute(source) || !/\.tsx?$/.test(source)) {
    problems.push(`invalid generated provider source: ${source}`);
    return files;
  }
  const runtimeFiles = files.filter((f) => f.path !== source);
  for (const f of runtimeFiles) {
    if (!CODE_EXT.test(f.path)) continue;
    for (const spec of importSpecifiers(f.content.toString('utf8'))) {
      const target = posix.normalize(posix.join(posix.dirname(f.path), spec));
      if (spec.startsWith('.') && (target === source || `${target}.ts` === source)) {
        problems.push(`${f.path}: generated provider still imports its authoring source '${spec}'`);
      }
    }
  }
  if (manifest.runtime?.daemonCommand?.some((arg) => typeof arg === 'string' && posix.normalize(arg) === source)) {
    problems.push(`generated provider daemon still executes its authoring source '${source}'`);
  }
  return runtimeFiles.map((f) => {
    if (!CODE_EXT.test(f.path) || !generated.test(f.content.toString('utf8'))) return f;
    try {
      return { path: f.path, content: Buffer.from(transformSync(f.content.toString('utf8'), {
        loader: 'js', minifyWhitespace: true, legalComments: 'eof',
      }).code) };
    } catch (error) {
      problems.push(`${f.path}: invalid generated JavaScript: ${error.message}`);
      return f;
    }
  });
}

/**
 * Turn the committed package files into the mirror's file set, or refuse.
 * Returns { ok:true, files } or { ok:false, problems }.
 */
export function buildMirror(files, { year } = {}) {
  const problems = [];
  const manifestFile = files.find((f) => f.path === 'papercusp.json');
  let manifest = null;
  if (!manifestFile) problems.push('papercusp.json is missing at the package root');
  else {
    try {
      manifest = JSON.parse(manifestFile.content.toString('utf8'));
    } catch (err) {
      problems.push(`papercusp.json does not parse: ${err.message}`);
    }
  }
  if (manifest && (typeof manifest.name !== 'string' || !manifest.name || typeof manifest.version !== 'string' || !manifest.version)) {
    problems.push('papercusp.json must declare a non-empty name and version (the Cupboard publish check requires both)');
  }
  const publicFiles = compiledProviderFiles(files, manifest, problems);
  problems.push(...selfContainmentProblems(publicFiles));
  problems.push(...internalReferenceProblems(publicFiles));

  const out = publicFiles.map((f) => ({ path: f.path, content: f.content }));
  const hasLicense = files.some((f) => /^LICEN[CS]E(?:\.(?:md|txt))?$/i.test(f.path));
  if (!hasLicense && manifest) {
    if (manifest.license === 'MIT') out.push({ path: 'LICENSE', content: Buffer.from(mitLicense({ year })) });
    else problems.push(`no LICENSE file and manifest license '${manifest.license ?? '(none)'}' is not one this exporter can generate (MIT only)`);
  }
  if (problems.length) return { ok: false, problems };
  out.sort((a, b) => a.path.localeCompare(b.path));
  return { ok: true, files: out };
}

/** Replace the mirror working tree's content with `files`, leaving `.git` alone. */
export function writeMirror(outDir, files) {
  mkdirSync(outDir, { recursive: true });
  for (const entry of readdirSync(outDir)) {
    if (entry === '.git') continue;
    rmSync(join(outDir, entry), { recursive: true, force: true });
  }
  for (const f of files) {
    const target = join(outDir, f.path);
    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, f.content);
  }
}

export const MIRROR_IDENTITY = { name: 'papercupai', email: 'papercupai@users.noreply.github.com' };

/**
 * Publish `files` to the git `remote` as one commit on top of its existing history.
 *
 * A mirror is UPDATED, never recreated: the remote is cloned and the export committed on top,
 * so the push is a fast-forward. (A fresh `git init` per export can only create a mirror; the
 * second publish is rejected as unrelated history.) An empty remote gets the first commit.
 * Content identical to the remote's makes no commit. Returns { status, head }.
 */
export function publishMirror({ outDir, remote, files, message, branch = 'main', identity = MIRROR_IDENTITY }) {
  if (existsSync(outDir) && readdirSync(outDir).length > 0) {
    throw new Error(`publish directory ${outDir} must not exist or be empty`);
  }
  const git = (args, cwd = outDir) => execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  const has = (ref) => {
    try {
      git(['rev-parse', '--verify', '--quiet', ref]);
      return true;
    } catch {
      return false;
    }
  };
  mkdirSync(outDir, { recursive: true });
  git(['clone', '--quiet', remote, outDir], dirname(outDir));
  if (has(`origin/${branch}`)) git(['checkout', '--quiet', '-B', branch, `origin/${branch}`]);
  writeMirror(outDir, files);
  git(['add', '-A']);
  if (has('HEAD') && git(['status', '--porcelain']) === '') return { status: 'unchanged', head: git(['rev-parse', 'HEAD']) };
  git(['-c', `user.name=${identity.name}`, '-c', `user.email=${identity.email}`, 'commit', '--quiet', '-m', message]);
  git(['push', '--quiet', 'origin', `HEAD:${branch}`]);
  return { status: 'published', head: git(['rev-parse', 'HEAD']) };
}

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const key = argv[i];
    if (!key.startsWith('--')) throw new Error(`unexpected argument: ${key}`);
    args[key.slice(2)] = argv[i + 1];
    i += 1;
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.package || !args.out) {
    console.error(
      'usage: plugin-mirror-export.mjs --package <name> --out <dir> [--ref <git-ref>] [--plugins-repo <dir>] [--push <git-remote>]',
    );
    process.exit(2);
  }
  const outDir = resolve(args.out);
  if (outDir === REPO_ROOT || outDir.startsWith(`${REPO_ROOT}/`)) {
    console.log('MIRROR_REFUSED --out must be outside the monorepo checkout');
    process.exit(1);
  }
  const pluginsRepo = args['plugins-repo'] ? resolve(args['plugins-repo']) : DEFAULT_PLUGINS_REPO;
  const ref = args.ref ?? 'HEAD';
  const files = readCommittedPackage({ pluginsRepo, name: args.package, ref });
  const result = buildMirror(files);
  if (!result.ok) {
    for (const p of result.problems) console.log(`MIRROR_REFUSED ${p}`);
    process.exit(1);
  }
  if (args.push) {
    const src = execFileSync('git', ['-C', pluginsRepo, 'log', '-1', '--format=%H', ref, '--', `plugins/${args.package}`], {
      encoding: 'utf8',
    }).trim();
    const published = publishMirror({
      outDir,
      remote: args.push,
      files: result.files,
      message: `Export ${args.package} from papercusp plugins@${src.slice(0, 12)}`,
    });
    console.log(
      published.status === 'published'
        ? `MIRROR_PUBLISHED head=${published.head} src=${src}`
        : `MIRROR_UNCHANGED head=${published.head}`,
    );
    return;
  }
  if (existsSync(outDir) && !existsSync(join(outDir, '.git')) && readdirSync(outDir).length > 0) {
    console.log('MIRROR_REFUSED --out exists, is not empty, and is not a git repository');
    process.exit(1);
  }
  writeMirror(outDir, result.files);
  for (const f of result.files) console.log(`MIRROR_FILE ${f.path}`);
  console.log(`MIRROR_OK files=${result.files.length}`);
}

if (isCliEntry(import.meta.url)) {
  main().catch((err) => {
    console.error(err?.stack ?? String(err));
    process.exit(1);
  });
}
